if('serviceWorker' in navigator){const script=document.currentScript.src;const base=new URL('./',script);navigator.serviceWorker.register(new URL('sw.js',base),{scope:base.pathname}).then(()=>navigator.serviceWorker.ready).then(()=>{const el=document.getElementById('offline');if(el)el.textContent='Für Offline-Nutzung vorbereitet';}).catch(()=>{const el=document.getElementById('offline');if(el)el.textContent='Offline-Vorbereitung fehlgeschlagen. Bitte online neu öffnen.';});}function net(){const el=document.getElementById('network');if(el)el.textContent=navigator.onLine?'Online':'Offline';}net();window.addEventListener('online',net);window.addEventListener('offline',net);